--当前448行
--------------------------------------------------------------
UPDATE Civics SET Cost = 300	WHERE CivicType = "TECH_CELESTIAL_NAVIGATION";	--雇佣兵原340
UPDATE Civics SET Cost = 420	WHERE CivicType = "TECH_CELESTIAL_NAVIGATION";	--探索原440
UPDATE ModifierArguments SET Value = 10	WHERE ModifierId = "DISCIPLINE_BARBARIANCOMBAT" 	AND Name = "Amount";	--纪律政策卡的效果改为同蛮族单位战斗时加10力
UPDATE ModifierArguments SET Value = 50	WHERE ModifierId = "ILKUM_BUILDERPRODUCTION" 		AND Name = "Amount";	--服役政策卡的效果改为生产建造者加50%的生产力
UPDATE ModifierArguments SET Value = 50	WHERE ModifierId = "PUBLICWORKS_BUILDERPRODUCTION" 	AND Name = "Amount";	--公共工程的效果与服役统一
UPDATE ModifierArguments SET Value = 5	WHERE ModifierId LIKE "RAJ_%" 	AND (ModifierId LIKE "%PERTRIBUTARY" OR ModifierId LIKE "%CITY_TRADE_ROUTE_GOLD" ) 	AND Name = "Amount";	--统治政策卡的效果提供的各项数值变为5点
UPDATE ModifierArguments SET Value = 4	WHERE ModifierId = "NEWDEAL_SPECIALTYAMENITY" 	AND Name = "Amount";	--高福利政策卡的效果改为所有城市加4住房加4宜居度
UPDATE ModifierArguments SET Value = 'ABILITY_SFDH100_ABILITY_DIGITAL_DEMOCRACY_BUFF'	WHERE ModifierId = "DIGITAL_DEMOCRACY_COMBAT_STRENGTH_PENALTY" 	AND Name = "AbilityType";	--和鳗鱼娘一起去二次元吧效果改为海军+10战斗力
UPDATE ModifierArguments SET Value = 30	WHERE (ModifierId = "RATIONALISM_BUILDING_YIELDS_HIGH_ADJACENCY" OR ModifierId = "RATIONALISM_BUILDING_YIELDS_HIGH_POP") 	AND Name = "Amount";	--理性主义政策卡的效果改为30%
UPDATE ModifierArguments SET Value = 50	WHERE (ModifierId LIKE "VETERANCY_ENCAMPMENT_%" OR ModifierId LIKE "VETERANCY_HARBOR_%") 	AND Name = "Amount";	--经验政策卡改为加速50%
UPDATE ModifierArguments SET Value = 8	WHERE ModifierId LIKE "LIMITANEI_GARRISONIDENTITY" AND Name = "Amount";	--边防军政策卡效果改为拥有驻军的城市加8忠诚度,加3防御力
UPDATE ModifierArguments SET Value = 4	WHERE ModifierId LIKE "FRESCOES_GREATARTISTPOINTS" AND Name = "Amount";	--壁画政策卡改为+4大艺术家点,每有一个艺术博物馆+2
UPDATE ModifierArguments SET Value = 2	WHERE ModifierId LIKE "MILITARYORGANIZATION_GREATGENERAL_MILITARYACADEMY" AND Name = "Amount";	--军事组织政策卡改为每有一个军事学院+2
UPDATE ModifierArguments SET Value = 8	WHERE ModifierId LIKE "PRAETORIUM_GOVERNORIDENTITY" AND Name = "Amount";	--司令部政策卡效果改为加8忠诚度
UPDATE ModifierArguments SET Value = 50	WHERE ModifierId LIKE "ENVIRONMENTALISM_BOOST_ALL_TOURISM" AND Name = "Amount";	--环境保护主义政策加50%旅游业绩
UPDATE ModifierArguments SET Value = 2	WHERE ModifierId LIKE "CONSERVATION_ANCIENT_WALL_TOURISM" AND Name = "Amount";	--远古城墙提供的旅游业绩改为2
UPDATE ModifierArguments SET Value = 4	WHERE ModifierId LIKE "CONSERVATION_MEDIEVAL_WALL_TOURISM" AND Name = "Amount";	--中世纪城墙提供的旅游业绩改为4
UPDATE ModifierArguments SET Value = 6	WHERE ModifierId LIKE "CONSERVATION_RENAISSANCE_WALL_TOURISM" AND Name = "Amount";	--文艺复兴城墙提供的旅游业绩改为6
UPDATE ModifierArguments SET Value = 2	WHERE ModifierId LIKE "TRADECONFEDERATION_TRADEROUTE%" AND Name = "Amount";	--贸易联盟政策卡改为对外贸易路线加2科技，加2文化
UPDATE ModifierArguments SET Value = 3	WHERE ModifierId = "INTERNATIONALSPACEAGENCY_SCIENCEPERTRIBUTARY" AND Name = "Amount";	--国际宇航局政策卡改为3%
UPDATE ModifierArguments SET Value = 3	WHERE ModifierId = "COLLECTIVEACTIVISM_CULTUREPERTRIBUTARY" AND Name = "Amount";	--集体行动政策卡改为3%
UPDATE Modifiers SET SubjectRequirementSetId = NULL	WHERE ModifierId = "NEWDEAL_SPECIALTYAMENITY" 	OR ModifierId = "NEWDEAL_SPECIALTYHOUSING";	--高福利政策卡的效果改为所有城市加4住房加4宜居度
UPDATE ObsoletePolicies SET ObsoletePolicy = 'POLICY_SFDH100_PEOPLES_ARMY'	WHERE PolicyType = "POLICY_RETAINERS";
UPDATE ObsoletePolicies SET ObsoletePolicy = 'POLICY_ECOMMERCE'	WHERE PolicyType = "POLICY_TRIANGULAR_TRADE";--三角贸易改为电子商务废除
DELETE FROM ObsoletePolicies WHERE PolicyType = 'POLICY_DISCIPLINE';--纪律永不废除
