INSERT OR REPLACE INTO CivicModifiers (CivicType,ModifierId)
SELECT 			'CIVIC_CIVIL_ENGINEERING',								'SFDH100_'||Building||'_PRODUCTION_BONUS'				FROM BuildingPrereqs WHERE PrereqBuilding IN ('BUILDING_MUSEUM_ART', 'BUILDING_FACTORY', 'BUILDING_TEMPLE', 'BUILDING_SHIPYARD', 'BUILDING_GOV_CITYSTATES', 'BUILDING_ZOO', 'BUILDING_ARMORY', 'BUILDING_BANK', 'BUILDING_UNIVERSITY')
UNION SELECT	'CIVIC_PROFESSIONAL_SPORTS',							'SFDH100_CIVIC_SPORTS_'||BuildingType||'_BONUS'			FROM Buildings		 WHERE (PrereqDistrict IS 'DISTRICT_ENTERTAINMENT_COMPLEX' OR PrereqDistrict IS 'DISTRICT_WATER_ENTERTAINMENT_COMPLEX') AND IsWonder IS 0
UNION SELECT	'CIVIC_CULTURAL_HERITAGE',								CivicModifiers.ModifierId								FROM CivicModifiers	 WHERE CivicType IS 'CIVIC_CONSERVATION' AND (ModifierId LIKE 'CONSERVATION_%' AND ModifierId LIKE '%_WALL_TOURISM');
DELETE FROM  CivicModifiers WHERE CivicType IS 'CIVIC_CONSERVATION' AND (ModifierId LIKE 'CONSERVATION_%' AND ModifierId LIKE '%_WALL_TOURISM');--城墙旅游业绩由保护地球改为文化遗产提供
DELETE FROM  CivicModifiers WHERE CivicType IN('CIVIC_DEFENSIVE_TACTICS','CIVIC_STATE_WORKFORCE','CIVIC_MEDIEVAL_FAIRES','CIVIC_GUILDS','CIVIC_CIVIL_ENGINEERING') AND ModifierId IS 'CIVIC_GRANT_PLAYER_GOVERNOR_POINTS';--ɾ������ս���������Ͷ����������ͼ��С����ᡢ��ľ���̵��ܶ�ͷ��
INSERT OR REPLACE INTO Modifiers (ModifierId,ModifierType)
SELECT 			'SFDH100_'||Building||'_PRODUCTION_BONUS',				'MODIFIER_PLAYER_CITIES_ADJUST_BUILDING_PRODUCTION' 	FROM BuildingPrereqs WHERE PrereqBuilding IN('BUILDING_MUSEUM_ART','BUILDING_FACTORY','BUILDING_TEMPLE','BUILDING_SHIPYARD','BUILDING_GOV_CITYSTATES','BUILDING_ZOO','BUILDING_ARMORY','BUILDING_BANK','BUILDING_UNIVERSITY')
UNION SELECT	'SFDH100_MILITARYRESEARCH_'||BuildingType||'_SCIENCE',	'MODIFIER_PLAYER_CITIES_ADJUST_BUILDING_YIELD_CHANGE'	FROM Buildings		 WHERE (PrereqDistrict IS 'DISTRICT_ENCAMPMENT' OR PrereqDistrict IS 'DISTRICT_HARBOR') AND IsWonder IS 0
UNION SELECT	'SFDH100_CIVIC_SPORTS_'||BuildingType||'_BONUS',		'MODIFIER_PLAYER_CITIES_ADJUST_BUILDING_YIELD_CHANGE'	FROM Buildings		 WHERE (PrereqDistrict IS 'DISTRICT_ENTERTAINMENT_COMPLEX' OR PrereqDistrict IS 'DISTRICT_WATER_ENTERTAINMENT_COMPLEX') AND IsWonder IS 0;
INSERT OR REPLACE INTO ModifierArguments (ModifierId,Name,Value)
SELECT			'SFDH100_'||Building||'_PRODUCTION_BONUS',				'BuildingType',				Building 					FROM BuildingPrereqs WHERE PrereqBuilding IN('BUILDING_MUSEUM_ART','BUILDING_FACTORY','BUILDING_TEMPLE','BUILDING_SHIPYARD','BUILDING_GOV_CITYSTATES','BUILDING_ZOO','BUILDING_ARMORY','BUILDING_BANK','BUILDING_UNIVERSITY')
UNION SELECT	'SFDH100_'||Building||'_PRODUCTION_BONUS',				'Amount',					15 							FROM BuildingPrereqs WHERE PrereqBuilding IN('BUILDING_MUSEUM_ART','BUILDING_FACTORY','BUILDING_TEMPLE','BUILDING_SHIPYARD','BUILDING_GOV_CITYSTATES','BUILDING_ZOO','BUILDING_ARMORY','BUILDING_BANK','BUILDING_UNIVERSITY')
UNION SELECT	'SFDH100_MILITARYRESEARCH_'||BuildingType||'_SCIENCE',	'BuildingType',				BuildingType				FROM Buildings		 WHERE (PrereqDistrict IS 'DISTRICT_ENCAMPMENT' OR PrereqDistrict IS 'DISTRICT_HARBOR') AND IsWonder IS 0
UNION SELECT	'SFDH100_MILITARYRESEARCH_'||BuildingType||'_SCIENCE',	'YieldType',				'YIELD_SCIENCE'				FROM Buildings		 WHERE (PrereqDistrict IS 'DISTRICT_ENCAMPMENT' OR PrereqDistrict IS 'DISTRICT_HARBOR') AND IsWonder IS 0
UNION SELECT	'SFDH100_MILITARYRESEARCH_'||BuildingType||'_SCIENCE',	'Amount',					3							FROM Buildings		 WHERE (PrereqDistrict IS 'DISTRICT_ENCAMPMENT' OR PrereqDistrict IS 'DISTRICT_HARBOR') AND IsWonder IS 0
UNION SELECT	'SFDH100_CIVIC_SPORTS_'||BuildingType||'_BONUS',		'BuildingType',				BuildingType				FROM Buildings		 WHERE (PrereqDistrict IS 'DISTRICT_ENTERTAINMENT_COMPLEX' OR PrereqDistrict IS 'DISTRICT_WATER_ENTERTAINMENT_COMPLEX') AND IsWonder IS 0
UNION SELECT	'SFDH100_CIVIC_SPORTS_'||BuildingType||'_BONUS',		'YieldType',				'YIELD_GOLD'				FROM Buildings		 WHERE (PrereqDistrict IS 'DISTRICT_ENTERTAINMENT_COMPLEX' OR PrereqDistrict IS 'DISTRICT_WATER_ENTERTAINMENT_COMPLEX') AND IsWonder IS 0
UNION SELECT	'SFDH100_CIVIC_SPORTS_'||BuildingType||'_BONUS',		'Amount',					3							FROM Buildings		 WHERE (PrereqDistrict IS 'DISTRICT_ENTERTAINMENT_COMPLEX' OR PrereqDistrict IS 'DISTRICT_WATER_ENTERTAINMENT_COMPLEX') AND IsWonder IS 0;
