INSERT OR REPLACE INTO GovernmentModifiers (GovernmentType,ModifierId) 
SELECT 			'GOVERNMENT_MONARCHY',					'SFDH100_MONARCHY_'||BuildingType||'_PRODUCTION_BONUS' 					FROM Buildings WHERE OuterDefenseHitPoints IS NOT NULL;
INSERT OR REPLACE INTO Modifiers (ModifierId,ModifierType)
SELECT 			'SFDH100_MONARCHY_'||BuildingType||'_PRODUCTION_BONUS',	'MODIFIER_PLAYER_CITIES_ADJUST_BUILDING_PRODUCTION' 	FROM Buildings WHERE OuterDefenseHitPoints IS NOT NULL;
INSERT OR REPLACE INTO ModifierArguments (ModifierId,Name,Value)
SELECT			'SFDH100_MONARCHY_'||BuildingType||'_PRODUCTION_BONUS',	'BuildingType',				BuildingType 				FROM Buildings WHERE OuterDefenseHitPoints IS NOT NULL
UNION SELECT	'SFDH100_MONARCHY_'||BuildingType||'_PRODUCTION_BONUS',	'Amount',					15 							FROM Buildings WHERE OuterDefenseHitPoints IS NOT NULL;
INSERT OR IGNORE INTO PolicyModifiers (PolicyType,ModifierId)
SELECT			'POLICY_GOV_AUTOCRACY',					GovernmentModifiers.ModifierId		FROM	GovernmentModifiers		WHERE	GovernmentType	IS	'GOVERNMENT_AUTOCRACY'
UNION SELECT	'POLICY_GOV_OLIGARCHY',					GovernmentModifiers.ModifierId		FROM	GovernmentModifiers		WHERE	GovernmentType	IS	'GOVERNMENT_OLIGARCHY' AND ModifierId NOT LIKE 'OLIGARCHY_MELEE'
UNION SELECT	'POLICY_GOV_CLASSICAL_REPUBLIC',		GovernmentModifiers.ModifierId		FROM	GovernmentModifiers		WHERE	GovernmentType	IS	'GOVERNMENT_CLASSICAL_REPUBLIC'
UNION SELECT	'POLICY_GOV_MONARCHY',					GovernmentModifiers.ModifierId		FROM	GovernmentModifiers		WHERE	GovernmentType	IS	'GOVERNMENT_MONARCHY' AND ModifierId NOT LIKE 'SFDH100_MONARCHY_CASTLE_TWO_INFLUENCE_TOKEN_MODIFIER'
UNION SELECT	'POLICY_GOV_THEOCRACY',					GovernmentModifiers.ModifierId		FROM	GovernmentModifiers		WHERE	GovernmentType	IS	'GOVERNMENT_THEOCRACY'
UNION SELECT	'POLICY_GOV_MERCHANT_REPUBLIC',			GovernmentModifiers.ModifierId		FROM	GovernmentModifiers		WHERE	GovernmentType	IS	'GOVERNMENT_MERCHANT_REPUBLIC'
UNION SELECT	'POLICY_GOV_FASCISM',					GovernmentModifiers.ModifierId		FROM	GovernmentModifiers		WHERE	GovernmentType	IS	'GOVERNMENT_FASCISM'
UNION SELECT	'POLICY_GOV_COMMUNISM',					GovernmentModifiers.ModifierId		FROM	GovernmentModifiers		WHERE	GovernmentType	IS	'GOVERNMENT_COMMUNISM'
UNION SELECT	'POLICY_GOV_DEMOCRACY',					GovernmentModifiers.ModifierId		FROM	GovernmentModifiers		WHERE	GovernmentType	IS	'GOVERNMENT_DEMOCRACY'
UNION SELECT	'POLICY_MILITARY_RESEARCH',				'SFDH100_MILITARYRESEARCH_'||BuildingType||'_SCIENCE'	FROM Buildings		 WHERE (PrereqDistrict IS 'DISTRICT_ENCAMPMENT' OR PrereqDistrict IS 'DISTRICT_HARBOR') AND IsWonder IS 0;
